c061.try_sql:
-- SET UNUSED hides the column, DROP UNUSED COLUMNS removes it physically
CREATE TABLE lab_c061_emp AS SELECT employee_id, last_name, email FROM employees;
ALTER TABLE lab_c061_emp SET UNUSED (email);
SELECT * FROM user_unused_col_tabs WHERE table_name = 'LAB_C061_EMP';
ALTER TABLE lab_c061_emp DROP UNUSED COLUMNS;
SELECT column_name FROM user_tab_cols WHERE table_name = 'LAB_C061_EMP';

c062.try_sql:
-- A READ ONLY table rejects DML (ORA-12081), READ WRITE allows writing again
CREATE TABLE lab_c062_t AS SELECT department_id, department_name FROM departments;
ALTER TABLE lab_c062_t READ ONLY;
SELECT table_name, read_only FROM user_tables WHERE table_name = 'LAB_C062_T';
DELETE FROM lab_c062_t;
ALTER TABLE lab_c062_t READ WRITE;
DELETE FROM lab_c062_t;

c510.try_sql:
-- Widening works, narrowing below the data does not (ORA-01441), an empty column can change type
CREATE TABLE lab_c510_t AS SELECT last_name, salary, CAST(NULL AS VARCHAR2(10)) AS note FROM employees;
ALTER TABLE lab_c510_t MODIFY (last_name VARCHAR2(50));
ALTER TABLE lab_c510_t MODIFY (last_name VARCHAR2(3));
ALTER TABLE lab_c510_t MODIFY (note DATE);
SELECT column_name, data_type, data_length
FROM   user_tab_columns
WHERE  table_name = 'LAB_C510_T'
ORDER  BY column_id;

