CREATE TABLE lab_c512_t (a NUMBER, b NUMBER, c NUMBER);
ALTER TABLE lab_c512_t DROP (b, c);
ALTER TABLE lab_c512_t DROP COLUMN a;
SELECT column_name FROM user_tab_columns WHERE table_name = 'LAB_C512_T';

c513.try_sql:
-- The default PTT (ON COMMIT DROP DEFINITION) disappears at the end of the transaction: CREATE TABLE commits
CREATE PRIVATE TEMPORARY TABLE ora$ptt_lab_c513_tx (id NUMBER);
CREATE PRIVATE TEMPORARY TABLE ora$ptt_lab_c513_sesja (id NUMBER) ON COMMIT PRESERVE DEFINITION;
CREATE TABLE lab_c513_t (id NUMBER);
-- Only the table with PRESERVE DEFINITION remains (DURATION = SESSION)
SELECT table_name, duration FROM user_private_temp_tables;

c1550.try_sql:
-- A PTT with a constraint: ORA-14451. CTAS works and does not commit
CREATE TABLE lab_c1550_t (id NUMBER);
INSERT INTO lab_c1550_t VALUES (1);
CREATE PRIVATE TEMPORARY TABLE ora$ptt_lab_c1550_pk (id NUMBER PRIMARY KEY);
CREATE PRIVATE TEMPORARY TABLE ora$ptt_lab_c1550_emp AS SELECT employee_id, last_name FROM employees;
ROLLBACK;
-- 0: the INSERT was not committed by creating the PTT
SELECT COUNT(*) AS wiersze FROM lab_c1550_t;

