c1552.try_sql:
-- Your session has a row in the GTT (PRESERVE ROWS): ALTER raises ORA-14450, after TRUNCATE it works
CREATE GLOBAL TEMPORARY TABLE lab_c1552_gtt (id NUMBER) ON COMMIT PRESERVE ROWS;
INSERT INTO lab_c1552_gtt VALUES (1);
ALTER TABLE lab_c1552_gtt ADD (note VARCHAR2(10));
TRUNCATE TABLE lab_c1552_gtt;
ALTER TABLE lab_c1552_gtt ADD (note VARCHAR2(10));
