c1553.try_sql:
-- An FK on a GTT: ORA-14455. PRIMARY KEY, CHECK and NOT NULL are allowed
CREATE TABLE lab_c1553_parent (id NUMBER CONSTRAINT lab_c1553_parent_pk PRIMARY KEY);
CREATE GLOBAL TEMPORARY TABLE lab_c1553_gtt (id NUMBER CONSTRAINT lab_c1553_pk PRIMARY KEY,
  parent_id NUMBER CONSTRAINT lab_c1553_fk REFERENCES lab_c1553_parent);
CREATE GLOBAL TEMPORARY TABLE lab_c1553_gtt (id NUMBER CONSTRAINT lab_c1553_pk PRIMARY KEY,
  qty NUMBER NOT NULL CONSTRAINT lab_c1553_ck CHECK (qty > 0));
SELECT constraint_name, constraint_type FROM user_constraints WHERE table_name = 'LAB_C1553_GTT';

c1557.try_sql:
-- Column a is in UNIQUE (a, b): DROP raises ORA-12991, CASCADE CONSTRAINTS drops the whole constraint
CREATE TABLE lab_c1557_t (a NUMBER, b NUMBER, c NUMBER, CONSTRAINT lab_c1557_uk UNIQUE (a, b));
ALTER TABLE lab_c1557_t DROP COLUMN a;
ALTER TABLE lab_c1557_t DROP COLUMN a CASCADE CONSTRAINTS;
SELECT constraint_name FROM user_constraints WHERE table_name = 'LAB_C1557_T';

c1558.try_sql:
-- After SET UNUSED: DROP COLUMN note raises ORA-00904, but you can add a new column note
CREATE TABLE lab_c1558_t (id NUMBER, note VARCHAR2(10));
ALTER TABLE lab_c1558_t SET UNUSED (note);
ALTER TABLE lab_c1558_t DROP COLUMN note;
ALTER TABLE lab_c1558_t ADD (note DATE);
-- The old column is hidden under the name SYS_C...$
SELECT column_name, data_type, hidden_column
FROM   user_tab_cols
WHERE  table_name = 'LAB_C1558_T'
ORDER  BY internal_column_id;

c1559.try_sql:
-- A deferred key: the duplicate goes through until COMMIT
CREATE TABLE lab_c1559_t (id NUMBER CONSTRAINT lab_c1559_pk PRIMARY KEY DEFERRABLE INITIALLY DEFERRED);
INSERT INTO lab_c1559_t VALUES (1);
INSERT INTO lab_c1559_t VALUES (1);
SELECT COUNT(*) AS przed_commit FROM lab_c1559_t;
-- DDL commits: ORA-02091 and the whole transaction is rolled back
ALTER TABLE lab_c1559_t ADD (note VARCHAR2(10));
SELECT COUNT(*) AS po_commit FROM lab_c1559_t;

